// ===========================================================================
//  BỘ NÃO BOT - anh CHỈ CẦN GÕ MÃ, bot tự tính giá vào / cắt lỗ / mục tiêu
//  từ dữ liệu giá (hỗ trợ - kháng cự). Anh vẫn có thể nhập tay để ghi đè.
//    /size BID            -> bot tự đề xuất 3 mức + tính khối lượng & R:R
//    /check BID           -> bot tự đề xuất 3 mức + bảng 7 câu
//    /size BID 42 39 46    -> anh tự nhập (ghi đè) vào/cắtlỗ/mục tiêu
// ===========================================================================
const OWNER = 5239928968;        // chỉ Chat ID này dùng được (chống người lạ)
const NAV   = 5000000;           // tài sản ròng (ĐỒNG) - sửa khi nạp thêm vốn
const MAX_POS_PCT = 100;         // trần % NAV / 1 vị thế
const RISK_PCT_DEF = 1.5;        // % NAV chấp nhận mất nếu cắt lỗ
// ===========================================================================

const upd = $input.first().json;
const msg = upd.message || upd.channel_post || {};
const text = (msg.text || '').trim();
const chatId = msg.chat && msg.chat.id;
const out = (m) => [{ json: { chatId, message: m } }];

if (String(chatId) !== String(OWNER)) return out('⛔ Bot riêng tư.');

const help = '🤖 *Bot CK — chỉ cần gõ MÃ*\n\n'
  + '🧮 `/size MÃ`\n   _vd: /size BID_ — bot tự tính vùng giá rồi ra khối lượng & R:R\n\n'
  + '🧭 `/check MÃ`\n   _vd: /check FPT_ — bot tự tính vùng giá + bảng 7 câu\n\n'
  + '✍️ Muốn tự nhập: `/size MÃ vào cắtlỗ mụctiêu` _(nghìn đồng, vd /size BID 42 39 46)_\n\n'
  + '_Mức bot đề xuất là GỢI Ý kỹ thuật từ hỗ trợ–kháng cự, không phải lệnh mua._';

if (!text || /^\/(start|help)\b/i.test(text)) return out(help);

const parts = text.split(/\s+/);
const cmd = parts[0].toLowerCase().replace(/@.*$/, '');
if (cmd !== '/size' && cmd !== '/check') return out('❓ Lệnh không hiểu.\n\n' + help);

const TICKER = (parts[1] || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
if (!TICKER) return out('⚠️ Thiếu mã. Chỉ cần gõ: `/size BID` hoặc `/check FPT`');

const aEntry  = parts[2] != null ? parseFloat(parts[2]) : NaN;
const aStop   = parts[3] != null ? parseFloat(parts[3]) : NaN;
const aTarget = parts[4] != null ? parseFloat(parts[4]) : NaN;
const RISK_PCT = (parts[5] != null && parseFloat(parts[5]) > 0) ? parseFloat(parts[5]) : RISK_PCT_DEF;

const fmtM = (d) => (d / 1e6).toFixed(d < 1e7 ? 2 : 1) + ' triệu';
const fmtP = (k) => Math.round(k * 1000).toLocaleString('vi-VN') + 'đ';

// ---- dữ liệu (3 nguồn đã chạy thật ở các workflow khác) -------------------
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFin = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };
const to = Math.floor(Date.now() / 1000), from = to - 60 * 60 * 24 * 200;

const fetchBars = async (t) => {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock', qs: { symbol: t, from, to, resolution: '1D' }, headers: hBar, json: true, timeout: 15000 });
    if (r && Array.isArray(r.c) && r.c.length) return r;
  } catch (e) {}
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://dchart-api.vndirect.com.vn/dchart/history', qs: { symbol: t, resolution: 'D', from, to }, headers: { ...hBar, Referer: 'https://dchart.vndirect.com.vn/' }, json: true, timeout: 15000 });
    if (r && Array.isArray(r.c) && r.c.length) return r;
  } catch (e) {}
  return null;
};
const fetchPE = async (t) => {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + t + '~itemCode:51006,1000043&sort=reportDate:desc&size=10', headers: hFin, json: false, timeout: 12000 });
    let p; try { p = typeof r === 'string' ? JSON.parse(r) : r; } catch (e) { p = null; }
    const m = {}; for (const d of ((p && p.data) || [])) if (!(d.ratioCode in m)) m[d.ratioCode] = d.value;
    return { pe: m['PRICE_TO_EARNINGS'], pe5: m['PRICE_TO_EARNINGS_AVG_CR_5Y'] };
  } catch (e) { return {}; }
};
const fetchFlow = async (t) => {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + t + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 12000 });
    return ((r && r.data) || []).map(x => (x.netVal || 0) / 1e9);
  } catch (e) { return []; }
};

// ---- vùng giá: hỗ trợ / kháng cự từ swing pivots --------------------------
const tickOf = (p) => p < 10000 ? 10 : p < 50000 ? 50 : 100;     // bước giá HOSE
const roundT = (p) => { const t = tickOf(p); return Math.round(p / t) * t; };
const pivots = (arr, w, kind) => {
  const r = [];
  for (let i = w; i < arr.length - w; i++) {
    let ok = true;
    for (let k = i - w; k <= i + w; k++) { if (k === i) continue; if (kind === 'low' ? arr[k] < arr[i] : arr[k] > arr[i]) { ok = false; break; } }
    if (ok) r.push({ i, v: arr[i] });
  }
  return r;
};
const dstr = (sec) => new Date(sec * 1000).toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });

const deriveLevels = (bars, entryOverrideK) => {
  const n = bars.c.length, lows = bars.l, highs = bars.h, times = bars.t;
  const closeD = bars.c[n - 1];
  const entryD = entryOverrideK > 0 ? entryOverrideK * 1000 : closeD;
  const lookI = Math.max(0, n - 130);                 // ~6 tháng gần nhất
  const pl = pivots(lows, 3, 'low').filter(p => p.i >= lookI && p.v < entryD * 0.997);
  const ph = pivots(highs, 3, 'high').filter(p => p.i >= lookI && p.v > entryD * 1.003);
  const note = [];

  // hỗ trợ: pivot đáy cao nhất còn nằm dưới giá vào; nếu không có -> đáy 20 phiên
  let sup, supDate = null;
  if (pl.length) { const best = pl.reduce((a, b) => b.v > a.v ? b : a); sup = best.v; supDate = dstr(times[best.i]); }
  else { sup = Math.min(...lows.slice(Math.max(0, n - 20))); note.push('hỗ trợ tạm tính = đáy 20 phiên'); }

  // kháng cự: pivot đỉnh thấp nhất nằm trên giá vào; nếu không có -> đỉnh 130 phiên; vẫn không -> +8%
  let res, resDate = null;
  if (ph.length) { const best = ph.reduce((a, b) => b.v < a.v ? b : a); res = best.v; resDate = dstr(times[best.i]); }
  else { const hi = Math.max(...highs.slice(lookI)); if (hi > entryD * 1.01) { res = hi; note.push('kháng cự tạm tính = đỉnh 6 tháng'); } else { res = entryD * 1.08; note.push('⚠️ giá đang ở vùng đỉnh, không có kháng cự rõ phía trên → mục tiêu tạm +8%'); } }

  let stopD = roundT(sup * 0.985);                    // cắt lỗ nhích dưới hỗ trợ ~1.5%
  if (stopD >= entryD) stopD = roundT(entryD * 0.92);
  let targetD = roundT(res);
  const eD = roundT(entryD);
  if (targetD <= eD) { targetD = roundT(eD * 1.08); note.push('mục tiêu điều chỉnh +8%'); }
  return { eD, stopD, targetD, supD: roundT(sup), resD: roundT(res), supDate, resDate, closeD: roundT(closeD), note };
};

// ---- lấy mức giá (tự động hoặc tay) ---------------------------------------
const manual = aEntry > 0 && aStop > 0;
let ENTRY, STOP, TARGET, prov;

if (manual) {
  if (!(aStop < aEntry)) return out('⚠️ Cắt lỗ phải THẤP HƠN giá vào.');
  ENTRY = aEntry; STOP = aStop; TARGET = aTarget > aEntry ? aTarget : 0;
  prov = '✍️ _Mức anh tự nhập_';
} else {
  const bars = await fetchBars(TICKER);
  if (!bars || !Array.isArray(bars.c) || bars.c.length < 12) {
    return out('🔴 Không lấy được dữ liệu giá *' + TICKER + '* (API lỗi hoặc mã sai).\nThử lại sau, hoặc nhập tay: `/' + cmd.slice(1) + ' ' + TICKER + ' vào cắtlỗ mụctiêu`');
  }
  const d = deriveLevels(bars, aEntry);
  ENTRY = d.eD / 1000; STOP = d.stopD / 1000; TARGET = d.targetD / 1000;
  prov = '📐 *Mức bot tự tính:*\n'
    + '· Vào ≈ giá hiện tại ' + fmtP(d.closeD / 1000) + '\n'
    + '· Cắt lỗ ' + fmtP(STOP) + ' _(dưới hỗ trợ ' + fmtP(d.supD / 1000) + (d.supDate ? ' lập ' + d.supDate : '') + ')_\n'
    + '· Mục tiêu ' + fmtP(TARGET) + ' _(kháng cự ' + fmtP(d.resD / 1000) + (d.resDate ? ' lập ' + d.resDate : '') + ')_'
    + (d.note.length ? '\n· ' + d.note.join('; ') : '');
}

const entryD = ENTRY * 1000;
const riskPerShare = (ENTRY - STOP) * 1000;
const byRisk = Math.floor((NAV * RISK_PCT / 100) / riskPerShare / 100) * 100;
const byCap = Math.floor((NAV * MAX_POS_PCT / 100) / entryD / 100) * 100;
const shares = Math.max(0, Math.min(byRisk, byCap));
const lotCost = entryD * 100;
const rr = TARGET > ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;

// ---------------------------- /size ----------------------------------------
if (cmd === '/size') {
  const L = ['🧮 *SIZING — ' + TICKER + '*', prov, '_NAV ' + fmtM(NAV) + ' · rủi ro ' + RISK_PCT + '%_', ''];
  if (shares <= 0) {
    L.push('→ Theo quy tắc rủi ro: chưa nên mua (chưa đủ 1 lô).');
    L.push(lotCost <= NAV ? '⚠️ Tối thiểu 1 lô = ' + fmtM(lotCost) + ' (' + (lotCost / NAV * 100).toFixed(0) + '% NAV → tập trung rất cao).' : '🔴 NAV không đủ 1 lô (' + fmtM(lotCost) + ').');
  } else {
    L.push('→ *MUA ' + shares.toLocaleString('vi-VN') + ' cp* (' + (shares / 100) + ' lô) = ' + fmtM(shares * entryD) + ' (' + (shares * entryD / NAV * 100).toFixed(0) + '% NAV)');
    L.push('→ Rủi ro thực nếu cắt lỗ: *' + fmtM(shares * riskPerShare) + '* (' + (shares * riskPerShare / NAV * 100).toFixed(2) + '% NAV)');
  }
  if (rr != null) L.push('→ *R:R ' + rr.toFixed(2) + '*' + (rr < 2 ? ' ⚠️ mỏng (<2, lời ít hơn 2× rủi ro)' : ' ✓ ổn'));
  L.push('');
  L.push('_Số bot tính là điểm khởi đầu — anh xem chart xác nhận trước khi đặt lệnh._');
  return out(L.join('\n'));
}

// ---------------------------- /check ---------------------------------------
const pe = await fetchPE(TICKER);
let q2 = '_thiếu P/E_';
if (pe.pe > 0 && pe.pe5 > 0) { const k = pe.pe / pe.pe5; q2 = 'P/E ' + pe.pe.toFixed(1) + ' vs TB5N ' + pe.pe5.toFixed(1) + ' → ' + (k <= 0.85 ? '🟢 RẺ so lịch sử' : k >= 1.15 ? '🔴 ĐẮT so lịch sử' : '🟡 quanh TB'); }
else if (pe.pe > 0) q2 = 'P/E ' + pe.pe.toFixed(1) + ' _(thiếu TB lịch sử)_';

const nets = await fetchFlow(TICKER);
let q4 = '_không lấy được_';
if (nets.length) { const dir = nets[0] > 1 ? 1 : nets[0] < -1 ? -1 : 0; let st = 0; for (const v of nets) { const s = v > 1 ? 1 : v < -1 ? -1 : 0; if (s === dir && dir) st++; else break; } q4 = 'phiên gần nhất ' + nets[0].toFixed(1) + ' tỷ' + (st >= 2 ? ' · ' + (dir > 0 ? 'GOM' : 'XẢ') + ' ' + st + ' phiên' : '') + ' · tổng 5p ' + nets.reduce((a, b) => a + b, 0).toFixed(1) + ' tỷ'; }

const q6 = (shares >= 100 ? 'mua ' + shares.toLocaleString('vi-VN') + ' cp (' + (shares * entryD / NAV * 100).toFixed(0) + '% NAV)' : (lotCost <= NAV ? '⚠️ chỉ đủ ~1 lô (' + (lotCost / NAV * 100).toFixed(0) + '% NAV)' : '🔴 NAV không đủ 1 lô')) + ' · R:R ' + (rr ? rr.toFixed(2) + (rr < 2 ? ' ⚠️' : '') : 'n/a');

const L = ['🧭 *BẢNG 7 CÂU — ' + TICKER + '*', prov, ''];
L.push('① Hiểu DN? _(anh tự trả lời)_');
L.push('② Rẻ/đắt? ✅ ' + q2);
L.push('③ Luận điểm & điều gì làm sai? _(anh tự viết)_');
L.push('④ Bối cảnh? ✅ Khối ngoại: ' + q4);
L.push('⑤ Thời điểm? _(xúc tác hay bắt dao rơi?)_');
L.push('⑥ Kích thước & R:R? ✅ ' + q6);
L.push('⑦ Thoát? ✅ Cắt lỗ ' + fmtP(STOP) + (TARGET ? ' · Mục tiêu ' + fmtP(TARGET) : ''));
L.push('');
L.push('📝 Phải tự trả lời ①③⑤. Không trọn 7 câu → ĐỨNG NGOÀI.');
L.push('_Mức giá là gợi ý kỹ thuật, không phải khuyến nghị mua/bán._');
return out(L.join('\n'));
